#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <dirent.h>
#include <time.h>
#include <errno.h>
#include <ctype.h>
#include <limits.h>
#include <fcntl.h>
#include <pwd.h>

/* Version info */
#define DUC_VERSION "1.5.0-rc1"
#define DUC_OPTIONS "cairo x11 ui sqlite3"

