    char *name;
    int type;             /* 0 file, 1 dir */
    uint64_t size_apparent;
    uint64_t size_actual;
    uint64_t file_count;  /* for dir: recursive file count */
    uint64_t dir_count;   /* for dir: recursive dir count  */
    struct entry *children;
    size_t n_children;
    size_t cap_children;
    uint64_t dev;         /* device id (only for dirs, for one-file-system) */
} Entry;

/* A top-level tree (indexed root) */
typedef struct tree {
    char *path;
    time_t timestamp;
    Entry root;
    /* top-N list: up to N largest files with full paths */
    struct topn_item *topn;
    size_t topn_count;
    /* histogram of apparent file sizes */
    uint64_t hist[64];
} Tree;

typedef struct topn_item {
    char *path;
    uint64_t size_apparent;
    uint64_t size_actual;
} TopNItem;

