cat > src/duc.c << 'DUCEOF'
/*
 * Duc - Disk Usage Checker
 * Reimplementation from behavioural observation.
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/statvfs.h>
#include <dirent.h>
#include <time.h>
#include <errno.h>
#include <ctype.h>
#include <limits.h>
#include <fcntl.h>
#include <pwd.h>
#include <fnmatch.h>
#include <getopt.h>

#define DUC_VERSION "1.5.0-rc1"
#define DUC_OPTIONS "cairo x11 ui sqlite3"

/* DB file magic */
#define DB_MAGIC "DUCDB\x01\x00\x00"
#define DB_MAGIC_LEN 8

static int opt_verbose = 0;
static int opt_quiet = 0;
static int opt_debug = 0;

/* ---------- Utility ---------- */

static void *xmalloc(size_t n) {
    void *p = calloc(1, n ? n : 1);
    if (!p) { fprintf(stderr, "out of memory\n"); exit(1); }
    return p;
}
static void *xrealloc(void *p, size_t n) {
    void *r = realloc(p, n);
    if (!r) { fprintf(stderr, "out of memory\n"); exit(1); }
    return r;
}
static char *xstrdup(const char *s) {
    if (!s) return NULL;
    size_t l = strlen(s);
    char *r = xmalloc(l + 1);
    memcpy(r, s, l + 1);
    return r;
}

static char *normalize_path(const char *in) {
    if (!in || !*in) return xstrdup(".");
    size_t n = strlen(in);
    char *out = xmalloc(n + 2);
    strcpy(out, in);
    /* strip trailing slashes except for "/" itself */
    while (n > 1 && out[n-1] == '/') { out[n-1] = 0; n--; }
    return out;
}

/* size format: like duc - < 1024 integer; else X.X{K,M,G,T,P,E} */
static void fmt_size(char *buf, size_t sz, uint64_t size, int bytes) {
    if (bytes) {
        snprintf(buf, sz, "%" PRIu64_if_needed "%lu", (unsigned long)size);
    }
}
DUCEOF
