#include "common.h"

int opt_verbose = 0;
int opt_quiet = 0;
int opt_debug = 0;

void *xmalloc(size_t n) {
    void *p = calloc(1, n ? n : 1);
    if (!p) { fprintf(stderr, "out of memory\n"); exit(1); }
    return p;
}
void *xrealloc(void *p, size_t n) {
    void *r = realloc(p, n);
    if (!r) { fprintf(stderr, "out of memory\n"); exit(1); }
    return r;
}
char *xstrdup(const char *s) {
    if (!s) return NULL;
    size_t l = strlen(s);
    char *r = xmalloc(l + 1);
    memcpy(r, s, l + 1);
    return r;
}

/* format a size in bytes, either as exact integer or human readable.
   The output matches `duc`'s formatter:
     - bytes mode: integer only
     - human: < 1024 => integer (no decimal), else X.X with unit */
void fmt_size(char *buf, size_t sz, uint64_t size, int bytes) {
    if (bytes) {
        snprintf(buf, sz, "%" PRIu64, size);
        return;
    }
    static const char *units = " KMGTPEZY";
    double v = (double)size;
    int unit = 0;
    if (size < 1024) {
        snprintf(buf, sz, "%" PRIu64, size);
        return;
    }
    while (v >= 1024.0 && unit < 8) {
        v /= 1024.0;
        unit++;
    }
    /* one decimal place, append unit char */
    snprintf(buf, sz, "%.1f%c", v, units[unit]);
}

/* count formatter - just integer but may be human-ish */
void fmt_count(char *buf, size_t sz, uint64_t c) {
    snprintf(buf, sz, "%" PRIu64, c);
}

char *normalize_path(const char *p) {
    if (!p || !*p) return xstrdup(".");
    size_t n = strlen(p);
    char *out = xmalloc(n + 2);
    memcpy(out, p, n + 1);
    while (n > 1 && out[n-1] == '/') { out[--n] = 0; }
    return out;
}

char *default_db_path(const char *override) {
    if (override && *override) return xstrdup(override);
    const char *env = getenv("DUC_DATABASE");
    if (env && *env) return xstrdup(env);
    const char *home = getenv("HOME");
    if (!home || !*home) {
        struct passwd *pw = getpwuid(getuid());
        if (pw) home = pw->pw_dir;
    }
    if (!home) home = "/";
    size_t l = strlen(home) + 10;
    char *r = xmalloc(l);
    snprintf(r, l, "%s/.duc.db", home);
    return r;
}

/* Entry helpers */
void entry_init(Entry *e, const char *name, int type) {
    memset(e, 0, sizeof(*e));
    e->name = name ? xstrdup(name) : NULL;
    e->type = type;
}
void entry_free(Entry *e) {
    free(e->name);
    for (size_t i = 0; i < e->n_children; i++) entry_free(&e->children[i]);
    free(e->children);
    memset(e, 0, sizeof(*e));
}
Entry *entry_add_child(Entry *parent, const char *name, int type) {
    if (parent->n_children == parent->cap_children) {
        size_t nc = parent->cap_children ? parent->cap_children * 2 : 8;
        parent->children = xrealloc(parent->children, nc * sizeof(Entry));
        memset(parent->children + parent->cap_children, 0,
               (nc - parent->cap_children) * sizeof(Entry));
        parent->cap_children = nc;
    }
    Entry *c = &parent->children[parent->n_children++];
    entry_init(c, name, type);
    return c;
}
Entry *entry_find_child(Entry *parent, const char *name) {
    for (size_t i = 0; i < parent->n_children; i++)
        if (strcmp(parent->children[i].name, name) == 0)
            return &parent->children[i];
    return NULL;
}

static int cmp_by_size_desc(const void *a, const void *b) {
    const Entry *ea = a, *eb = b;
    /* actual size primary, apparent tiebreak, then name */
    if (ea->size_actual != eb->size_actual)
        return (eb->size_actual > ea->size_actual) ? 1 : -1;
    if (ea->size_apparent != eb->size_apparent)
        return (eb->size_apparent > ea->size_apparent) ? 1 : -1;
    return strcmp(ea->name, eb->name);
}
static int cmp_by_name(const void *a, const void *b) {
    const Entry *ea = a, *eb = b;
    return strcmp(ea->name, eb->name);
}

void entry_sort(Entry *e, int by_name, int recursive) {
    if (e->n_children > 0) {
        qsort(e->children, e->n_children, sizeof(Entry),
              by_name ? cmp_by_name : cmp_by_size_desc);
        if (recursive)
            for (size_t i = 0; i < e->n_children; i++)
                entry_sort(&e->children[i], by_name, 1);
    }
}
