static int r_u16(FILE *f, uint16_t *v){ int a=fgetc(f), b=fgetc(f); if(a==EOF||b==EOF) return -1; *v = (uint16_t)(a | (b<<8)); return 0; }
static int r_u32(FILE *f, uint32_t *v){ uint32_t x=0; for(int i=0;i<4;i++){int c=fgetc(f); if(c==EOF) return -1; x |= ((uint32_t)c)<<(i*8);} *v=x; return 0; }
static int r_u64(FILE *f, uint64_t *v){ uint64_t x=0; for(int i=0;i<8;i++){int c=fgetc(f); if(c==EOF) return -1; x |= ((uint64_t)c)<<(i*8);} *v=x; return 0; }
static int r_i64(FILE *f, int64_t *v) { uint64_t u; if(r_u64(f,&u)<0) return -1; *v=(int64_t)u; return 0; }
static int r_str(FILE *f, char **out) {
    uint16_t l;
    if (r_u16(f, &l) < 0) return -1;
    char *s = xmalloc((size_t)l + 1);
    if (l && fread(s, 1, l, f) != l) { free(s); return -1; }
    s[l] = 0;
    *out = s;
    return 0;
}

static void write_entry(FILE *f, Entry *e) {
    w_str(f, e->name ? e->name : "");
    w_u8(f, (uint8_t)e->type);
    w_u64(f, e->size_apparent);
    w_u64(f, e->size_actual);
    w_u64(f, e->file_count);
    w_u64(f, e->dir_count);
    w_u64(f, e->dev);
    w_u32(f, (uint32_t)e->n_children);
    for (size_t i = 0; i < e->n_children; i++)
        write_entry(f, &e->children[i]);
}

static int read_entry(FILE *f, Entry *e) {
    char *name = NULL;
    if (r_str(f, &name) < 0) return -1;
    uint8_t type;
    if (r_u8(f, &type) < 0) { free(name); return -1; }
    entry_init(e, NULL, type);
    e->name = name;
    if (r_u64(f, &e->size_apparent) < 0) return -1;
    if (r_u64(f, &e->size_actual) < 0) return -1;
    if (r_u64(f, &e->file_count) < 0) return -1;
    if (r_u64(f, &e->dir_count) < 0) return -1;
    if (r_u64(f, &e->dev) < 0) return -1;
    uint32_t nc;
    if (r_u32(f, &nc) < 0) return -1;
    if (nc) {
        e->children = xmalloc(nc * sizeof(Entry));
        memset(e->children, 0, nc * sizeof(Entry));
        e->cap_children = nc;
        for (uint32_t i = 0; i < nc; i++) {
            if (read_entry(f, &e->children[i]) < 0) return -1;
            e->n_children = i + 1;
        }
    }
    return 0;
}

Database *db_new(void) {
    Database *db = xmalloc(sizeof(Database));
    return db;
}
void db_free(Database *db) {
    if (!db) return;
    for (size_t i = 0; i < db->n_trees; i++) {
        free(db->trees[i].path);
        entry_free(&db->trees[i].root);
        for (size_t j = 0; j < db->trees[i].topn_count; j++)
            free(db->trees[i].topn[j].path);
        free(db->trees[i].topn);
    }
    free(db->trees);
    free(db);
}

int db_load(Database *db, const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        if (errno == ENOENT) {
            fprintf(stderr, "Error opening: %s - Database not found\n", path);
            fprintf(stderr, "Database not found\n");
        } else {
            fprintf(stderr, "Error opening: %s - %s\n", path, strerror(errno));
            fprintf(stderr, "%s\n", strerror(errno));
        }
        return -1;
    }
    char magic[DB_MAGIC_LEN];
    if (fread(magic, 1, DB_MAGIC_LEN, f) != DB_MAGIC_LEN ||
        memcmp(magic, DB_MAGIC, DB_MAGIC_LEN) != 0) {
        fprintf(stderr, "Error opening: %s - Database corrupt and not usable\n", path);
        fprintf(stderr, "Database corrupt and not usable\n");
        fclose(f);
        return -1;
    }
    uint32_t n_trees;
    if (r_u32(f, &n_trees) < 0) goto corrupt;
    db->trees = xmalloc(n_trees * sizeof(Tree));
    memset(db->trees, 0, n_trees * sizeof(Tree));
    db->cap_trees = n_trees;
    for (uint32_t i = 0; i < n_trees; i++) {
        Tree *t = &db->trees[i];
        if (r_str(f, &t->path) < 0) goto corrupt;
        int64_t ts;
        if (r_i64(f, &ts) < 0) goto corrupt;
        t->timestamp = (time_t)ts;
        for (int k = 0; k < 64; k++) {
            if (r_u64(f, &t->hist[k]) < 0) goto corrupt;
        }
        uint32_t tn;
        if (r_u32(f, &tn) < 0) goto corrupt;
        if (tn) {
            t->topn = xmalloc(tn * sizeof(TopNItem));
            memset(t->topn, 0, tn * sizeof(TopNItem));
            t->topn_cap = tn;
            for (uint32_t j = 0; j < tn; j++) {
                if (r_str(f, &t->topn[j].path) < 0) goto corrupt;
                if (r_u64(f, &t->topn[j].size_apparent) < 0) goto corrupt;
                if (r_u64(f, &t->topn[j].size_actual) < 0) goto corrupt;
                t->topn_count = j + 1;
            }
        }
        if (read_entry(f, &t->root) < 0) goto corrupt;
        db->n_trees = i + 1;
    }
    fclose(f);
    return 0;
corrupt:
    fprintf(stderr, "Error opening: %s - Database corrupt and not usable\n", path);
    fprintf(stderr, "Database corrupt and not usable\n");
    fclose(f);
    return -1;
}

int db_save(Database *db, const char *path) {
    FILE *f = fopen(path, "wb");
    if (!f) {
        fprintf(stderr, "Error opening: %s - %s\n", path, strerror(errno));
        return -1;
    }
    fwrite(DB_MAGIC, 1, DB_MAGIC_LEN, f);
    w_u32(f, (uint32_t)db->n_trees);
    for (size_t i = 0; i < db->n_trees; i++) {
        Tree *t = &db->trees[i];
        w_str(f, t->path);
        w_i64(f, (int64_t)t->timestamp);
        for (int k = 0; k < 64; k++) w_u64(f, t->hist[k]);
        w_u32(f, (uint32_t)t->topn_count);
        for (size_t j = 0; j < t->topn_count; j++) {
            w_str(f, t->topn[j].path);
            w_u64(f, t->topn[j].size_apparent);
            w_u64(f, t->topn[j].size_actual);
        }
        write_entry(f, &t->root);
    }
    fclose(f);
    return 0;
}

Tree *db_find_tree(Database *db, const char *path) {
    if (!db) return NULL;
    Tree *best = NULL;
    size_t best_len = 0;
    size_t plen = strlen(path);
    for (size_t i = 0; i < db->n_trees; i++) {
        Tree *t = &db->trees[i];
        size_t tlen = strlen(t->path);
        if (tlen > plen) continue;
        if (strncmp(t->path, path, tlen) != 0) continue;
        if (tlen < plen && path[tlen] != '/' &&
            !(tlen == 1 && t->path[0] == '/')) continue;
        if (tlen > best_len) { best = t; best_len = tlen; }
    }
    return best;
}

/* Walk "path" under tree, returning (entry, rel) - if not found, returns NULL */
Tree *db_find_tree_or_sub(Database *db, const char *path, Entry **out_entry, char **out_relpath) {
    Tree *t = db_find_tree(db, path);
    if (!t) return NULL;
    const char *rel = path + strlen(t->path);
    while (*rel == '/') rel++;
    Entry *e = &t->root;
    if (*rel) {
        /* descend into path components */
        char *dup = xstrdup(rel);
        char *s = dup;
        while (*s) {
            char *slash = strchr(s, '/');
            if (slash) *slash = 0;
            Entry *c = entry_find_child(e, s);
            if (!c || c->type != ENT_DIR) {
                if (slash) {
                    free(dup);
                    return NULL;
                }
                /* terminal: could be a file, but ls etc assume dir */
                if (!c) { free(dup); return NULL; }
                e = c;
                break;
            }
            e = c;
            if (!slash) break;
            s = slash + 1;
        }
        free(dup);
    }
    *out_entry = e;
    if (out_relpath) *out_relpath = xstrdup(rel);
    return t;
}

Tree *db_add_tree(Database *db, const char *path) {
    /* Replace if exists */
    for (size_t i = 0; i < db->n_trees; i++) {
        if (strcmp(db->trees[i].path, path) == 0) {
            free(db->trees[i].path);
            entry_free(&db->trees[i].root);
            for (size_t j = 0; j < db->trees[i].topn_count; j++)
                free(db->trees[i].topn[j].path);
            free(db->trees[i].topn);
            memset(&db->trees[i], 0, sizeof(Tree));
            db->trees[i].path = xstrdup(path);
            return &db->trees[i];
        }
    }
    if (db->n_trees == db->cap_trees) {
        size_t nc = db->cap_trees ? db->cap_trees * 2 : 4;
        db->trees = xrealloc(db->trees, nc * sizeof(Tree));
        memset(db->trees + db->cap_trees, 0, (nc - db->cap_trees) * sizeof(Tree));
        db->cap_trees = nc;
    }
    Tree *t = &db->trees[db->n_trees++];
    t->path = xstrdup(path);
    return t;
}
