#include "common.h"
#include <sys/statvfs.h>
#include <sys/time.h>

typedef struct {
    char *db;
    int bytes;
    int buckets;
    char **excludes;
    size_t n_excludes;
    int check_hard_links;
    int force;
    char **fs_excludes;
    size_t n_fs_excludes;
    char **fs_includes;
    size_t n_fs_includes;
    int hide_file_names;
    int uid_set;
    uid_t uid;
    int topn_limit;
    uint64_t topn_min;
    int max_depth;
    int one_fs;
    int progress;
    int dry_run;
    int uncompressed;
} IndexOpts;

/* Running stats */
typedef struct {
    Tree *tree;
    int check_hard_links;
    /* hard link tracking: simple dynamic list */
    struct { dev_t dev; ino_t ino; } *seen;
    size_t n_seen, cap_seen;
    /* excludes */
    char **excludes;
    size_t n_excludes;
    int one_fs;
    dev_t root_dev;
    int uid_set;
    uid_t uid;
    int max_depth;
    int hide_file_names;
    uint64_t file_count;
    uint64_t dir_count;
    uint64_t total_size;
    uint64_t skipped_bytes;
} IdxCtx;

static int already_seen(IdxCtx *ctx, dev_t dev, ino_t ino) {
    for (size_t i = 0; i < ctx->n_seen; i++)
        if (ctx->seen[i].dev == dev && ctx->seen[i].ino == ino) return 1;
    if (ctx->n_seen == ctx->cap_seen) {
        size_t nc = ctx->cap_seen ? ctx->cap_seen * 2 : 256;
        ctx->seen = xrealloc(ctx->seen, nc * sizeof(*ctx->seen));
        ctx->cap_seen = nc;
    }
    ctx->seen[ctx->n_seen].dev = dev;
    ctx->seen[ctx->n_seen].ino = ino;
    ctx->n_seen++;
    return 0;
}

static int name_excluded(IdxCtx *ctx, const char *name) {
    for (size_t i = 0; i < ctx->n_excludes; i++)
        if (fnmatch(ctx->excludes[i], name, 0) == 0) return 1;
    return 0;
}

static void update_histogram(uint64_t *hist, uint64_t size) {
    int bucket = 0;
    uint64_t v = size;
    while (v >= 2 && bucket < 63) { v >>= 1; bucket++; }
    if (size == 0) bucket = 0;
    if (bucket >= 64) bucket = 63;
    hist[bucket]++;
}

static void maybe_add_topn(Tree *t, const char *full_path, uint64_t sa, uint64_t sac) {
    if (t->topn_limit == 0) return;
    if (sa < t->topn_min) return;
    if (t->topn_count < t->topn_limit) {
        if (t->topn_count == t->topn_cap) {
            size_t nc = t->topn_cap ? t->topn_cap * 2 : 16;
            if (nc > t->topn_limit) nc = t->topn_limit;
            t->topn = xrealloc(t->topn, nc * sizeof(TopNItem));
            memset(t->topn + t->topn_cap, 0, (nc - t->topn_cap) * sizeof(TopNItem));
            t->topn_cap = nc;
        }
        t->topn[t->topn_count].path = xstrdup(full_path);
        t->topn[t->topn_count].size_apparent = sa;
        t->topn[t->topn_count].size_actual = sac;
        t->topn_count++;
        return;
    }
    /* find minimum in topn, evict if new one is bigger */
    size_t min_i = 0;
    for (size_t i = 1; i < t->topn_count; i++)
        if (t->topn[i].size_apparent < t->topn[min_i].size_apparent) min_i = i;
    if (sa > t->topn[min_i].size_apparent) {
        free(t->topn[min_i].path);
        t->topn[min_i].path = xstrdup(full_path);
        t->topn[min_i].size_apparent = sa;
        t->topn[min_i].size_actual = sac;
    }
}

/* Recursively scan path, fill entry e. Returns 0 on success. */
static int scan_dir(IdxCtx *ctx, const char *path, Entry *e, int depth) {
    DIR *dir = opendir(path);
    if (!dir) {
        if (!opt_quiet) {
            fprintf(stderr, "Skipping %s: %s\n", path, strerror(errno));
        }
        return -1;
