/* Recursively scan path, fill entry e. Returns 0 on success. */
static int scan_dir(IdxCtx *ctx, const char *path, Entry *e, int depth) {
    DIR *dir = opendir(path);
    if (!dir) {
        if (!opt_quiet) {
            fprintf(stderr, "Skipping %s: %s\n", path, strerror(errno));
        }
        return -1;
    }
    struct dirent *de;
    while ((de = readdir(dir))) {
        if (strcmp(de->d_name, ".") == 0 || strcmp(de->d_name, "..") == 0) continue;
        if (name_excluded(ctx, de->d_name)) continue;
        char full[PATH_MAX];
        snprintf(full, sizeof(full), "%s/%s", path, de->d_name);
        struct stat st;
        if (lstat(full, &st) != 0) continue;
        if (ctx->uid_set && st.st_uid != ctx->uid) continue;
        if (S_ISDIR(st.st_mode)) {
            if (ctx->one_fs && st.st_dev != ctx->root_dev) continue;
            /* depth limit: at deeper than max_depth, include dir but don't store its name as child? 
               Actually the doc says "limit directory names to given depth"; we implement simply:
               if depth+1 > max_depth, skip storing name but still account for sizes. */
            int skip_entry = (ctx->max_depth > 0 && depth + 1 > ctx->max_depth);
            Entry *ce = NULL;
            if (!skip_entry) {
                ce = entry_add_child(e, de->d_name, ENT_DIR);
                ce->dev = (uint64_t)st.st_dev;
            } else {
                /* use a temporary entry to accumulate sizes we'll roll up */
                ce = xmalloc(sizeof(Entry));
                entry_init(ce, de->d_name, ENT_DIR);
            }
            scan_dir(ctx, full, ce, depth + 1);
            /* roll up into parent */
            e->size_apparent += ce->size_apparent;
            e->size_actual += ce->size_actual;
            e->file_count += ce->file_count;
            e->dir_count += ce->dir_count + 1;
            ctx->dir_count++;
            if (skip_entry) {
                entry_free(ce);
                free(ce);
            }
        } else if (S_ISREG(st.st_mode) || S_ISLNK(st.st_mode) ||
                   S_ISFIFO(st.st_mode) || S_ISBLK(st.st_mode) ||
                   S_ISCHR(st.st_mode) || S_ISSOCK(st.st_mode)) {
            if (ctx->check_hard_links && st.st_nlink > 1 &&
                already_seen(ctx, st.st_dev, st.st_ino)) continue;
            uint64_t sa = (uint64_t)st.st_size;
            uint64_t sac = (uint64_t)st.st_blocks * 512;
            Entry *ce = entry_add_child(e, ctx->hide_file_names ? "" : de->d_name, ENT_FILE);
            ce->size_apparent = sa;
            ce->size_actual = sac;
