static void parse_list(char *val, char ***out, size_t *n) {
    /* comma-separated */
    char *p = val;
    while (p && *p) {
        char *c = strchr(p, ',');
        if (c) *c = 0;
        *out = xrealloc(*out, (*n + 1) * sizeof(char*));
        (*out)[(*n)++] = xstrdup(p);
        if (!c) break;
        p = c + 1;
    }
}

