            if (skip_entry) {
                entry_free(ce);
                free(ce);
            }
        } else if (S_ISREG(st.st_mode) || S_ISLNK(st.st_mode) ||
                   S_ISFIFO(st.st_mode) || S_ISBLK(st.st_mode) ||
                   S_ISCHR(st.st_mode) || S_ISSOCK(st.st_mode)) {
            if (ctx->check_hard_links && st.st_nlink > 1 &&
                already_seen(ctx, st.st_dev, st.st_ino)) continue;
            uint64_t sa = (uint64_t)st.st_size;
            uint64_t sac = (uint64_t)st.st_blocks * 512;
            Entry *ce = entry_add_child(e, ctx->hide_file_names ? "" : de->d_name, ENT_FILE);
            ce->size_apparent = sa;
            ce->size_actual = sac;
            e->size_apparent += sa;
            e->size_actual += sac;
            e->file_count += 1;
            ctx->file_count++;
            update_histogram(ctx->tree->hist, sa);
            maybe_add_topn(ctx->tree, full, sa, sac);
        }
    }
    closedir(dir);
    return 0;
}

static void usage_index(void) {
    print_help_sub("index");
}

static void parse_list(char *val, char ***out, size_t *n) {
    /* comma-separated */
    char *p = val;
    while (p && *p) {
        char *c = strchr(p, ',');
        if (c) *c = 0;
        *out = xrealloc(*out, (*n + 1) * sizeof(char*));
        (*out)[(*n)++] = xstrdup(p);
        if (!c) break;
        p = c + 1;
    }
}

int cmd_index(int argc, char **argv) {
    IndexOpts o = {0};
    o.buckets = 48;
    o.topn_limit = 10;
    o.topn_min = 0;
    /* parse options */
    int i;
    char **paths = xmalloc(argc * sizeof(char*));
    size_t n_paths = 0;
    for (i = 1; i < argc; i++) {
        const char *a = argv[i];
        if (strcmp(a, "-h") == 0 || strcmp(a, "--help") == 0) {
            usage_index(); free(o.db); free(paths); return 0;
        } else if (strcmp(a, "-b") == 0 || strcmp(a, "--bytes") == 0) {
            o.bytes = 1;
        } else if (strncmp(a, "--buckets=", 10) == 0) {
            o.buckets = atoi(a + 10);
        } else if (strcmp(a, "-B") == 0) {
            o.buckets = atoi(argv[++i]);
        } else if (strncmp(a, "--database=", 11) == 0) {
            free(o.db); o.db = xstrdup(a + 11);
        } else if (strcmp(a, "-d") == 0) {
            free(o.db); o.db = xstrdup(argv[++i]);
        } else if (strncmp(a, "--exclude=", 10) == 0) {
            o.excludes = xrealloc(o.excludes, (o.n_excludes+1)*sizeof(char*));
            o.excludes[o.n_excludes++] = xstrdup(a+10);
        } else if (strcmp(a, "-e") == 0) {
            o.excludes = xrealloc(o.excludes, (o.n_excludes+1)*sizeof(char*));
            o.excludes[o.n_excludes++] = xstrdup(argv[++i]);
        } else if (strcmp(a, "-H") == 0 || strcmp(a, "--check-hard-links") == 0) {
            o.check_hard_links = 1;
        } else if (strcmp(a, "-f") == 0 || strcmp(a, "--force") == 0) {
            o.force = 1;
        } else if (strncmp(a, "--fs-exclude=", 13) == 0) {
            char *v = xstrdup(a + 13);
            parse_list(v, &o.fs_excludes, &o.n_fs_excludes);
            free(v);
        } else if (strncmp(a, "--fs-include=", 13) == 0) {
            char *v = xstrdup(argv[i] + 13);
            parse_list(v, &o.fs_includes, &o.n_fs_includes);
            free(v);
        } else if (strcmp(a, "--hide-file-names") == 0) {
            o.hide_file_names = 1;
        } else if (strncmp(a, "--uid=", 6) == 0) {
            o.uid_set = 1; o.uid = (uid_t)atoi(a + 6);
        } else if (strcmp(a, "-U") == 0) {
            o.uid_set = 1; o.uid = (uid_t)atoi(argv[++i]);
        } else if (strncmp(a, "--topn=", 7) == 0) {
            o.topn_limit = atoi(a + 7);
        } else if (strcmp(a, "-T") == 0) {
            o.topn_limit = atoi(argv[++i]);
        } else if (strncmp(a, "--topn-min=", 11) == 0) {
            o.topn_min = strtoull(a + 11, NULL, 10);
        } else if (strcmp(a, "-M") == 0) {
            o.topn_min = strtoull(argv[++i], NULL, 10);
        } else if (strncmp(a, "--username=", 11) == 0) {
            struct passwd *pw = getpwnam(a + 11);
            if (pw) { o.uid_set = 1; o.uid = pw->pw_uid; }
        } else if (strcmp(a, "-u") == 0) {
            struct passwd *pw = getpwnam(argv[++i]);
            if (pw) { o.uid_set = 1; o.uid = pw->pw_uid; }
        } else if (strncmp(a, "--max-depth=", 12) == 0) {
            o.max_depth = atoi(a + 12);
        } else if (strcmp(a, "-m") == 0) {
            o.max_depth = atoi(argv[++i]);
        } else if (strcmp(a, "-x") == 0 || strcmp(a, "--one-file-system") == 0) {
            o.one_fs = 1;
        } else if (strcmp(a, "-p") == 0 || strcmp(a, "--progress") == 0) {
            o.progress = 1;
        } else if (strcmp(a, "--dry-run") == 0) {
            o.dry_run = 1;
        } else if (strcmp(a, "--uncompressed") == 0) {
            o.uncompressed = 1;
        } else if (a[0] == '-' && a[1] != 0) {
            fprintf(stderr, "Error: Unknown option '%s'\n", a);
            free(o.db); free(paths); return 1;
        } else {
            paths[n_paths++] = xstrdup(a);
        }
    }

    if (n_paths == 0) {
        fprintf(stderr, "Required index PATH missing.\n");
        usage_index();
        free(o.db); free(paths); return 1;
    }

    char *dbpath = default_db_path(o.db);
    Database *db = db_new();
    /* Try to load existing database; ignore errors if not exist */
    struct stat dst;
    if (stat(dbpath, &dst) == 0) {
        if (db_load(db, dbpath) != 0 && !o.force) {
            db_free(db);
            free(dbpath); free(o.db);
            for (size_t k=0;k<n_paths;k++) free(paths[k]);
            free(paths);
            return 1;
        }
    }

    struct timeval t0, t1;
    gettimeofday(&t0, NULL);

    uint64_t total_files = 0, total_dirs = 0, total_bytes = 0;
    for (size_t p = 0; p < n_paths; p++) {
        struct statvfs svfs;
        if (statvfs(paths[p], &svfs) != 0) {
            fprintf(stderr, "Can't run statvfs on %s\n", paths[p]);
            continue;
        }
        char *abspath = realpath(paths[p], NULL);
        if (!abspath) abspath = xstrdup(paths[p]);
        char *nabs = normalize_path(abspath);
        free(abspath);
        /* Create tree */
        Tree *t = db_add_tree(db, nabs);
        t->timestamp = time(NULL);
        t->topn_limit = o.topn_limit;
        t->topn_min = o.topn_min;
        entry_init(&t->root, nabs, ENT_DIR);
        struct stat st;
        if (lstat(nabs, &st) == 0) {
            t->root.dev = (uint64_t)st.st_dev;
        }
        IdxCtx ctx = {0};
        ctx.tree = t;
        ctx.check_hard_links = o.check_hard_links;
        ctx.excludes = o.excludes;
        ctx.n_excludes = o.n_excludes;
        ctx.one_fs = o.one_fs;
        ctx.root_dev = st.st_dev;
        ctx.uid_set = o.uid_set;
        ctx.uid = o.uid;
        ctx.max_depth = o.max_depth;
        ctx.hide_file_names = o.hide_file_names;
        scan_dir(&ctx, nabs, &t->root, 0);
        t->root.file_count += ctx.file_count;
        /* dir_count: don't count the root itself */
        t->root.dir_count += ctx.dir_count;
        total_files += ctx.file_count;
        total_dirs += ctx.dir_count + 1;
        total_bytes += t->root.size_actual;
        free(ctx.seen);
        free(nabs);
    }

    gettimeofday(&t1, NULL);
    long secs = t1.tv_sec - t0.tv_sec;
    if (secs < 1) secs = 1;
    if (!o.dry_run) {
        if (db_save(db, dbpath) != 0) {
            db_free(db);
            free(dbpath); free(o.db);
            for (size_t k=0;k<n_paths;k++) free(paths[k]);
            free(paths);
            return 1;
        }
    }
    char sbuf[64];
    fmt_size(sbuf, sizeof(sbuf), total_bytes, o.bytes);
    if (!opt_quiet) {
        fprintf(stderr, "Indexed %" PRIu64 " files and %" PRIu64 " directories, (%s%s total) in %ld seconds\n",
                total_files, total_dirs - n_paths < 0 ? 0 : total_dirs - n_paths,
                sbuf, o.bytes ? "" : "B", secs);
    }
    db_free(db);
    free(dbpath); free(o.db);
    for (size_t k=0;k<n_paths;k++) free(paths[k]);
    free(paths);
    return 0;
}
