    int check_hard_links;
    struct { dev_t dev; ino_t ino; } *seen;
    size_t n_seen, cap_seen;
    char **excludes;
    size_t n_excludes;
    int one_fs;
    dev_t root_dev;
    int uid_set;
    uid_t uid;
    int max_depth;
    int hide_file_names;
    int bytes;
