} IdxCtx;

static int already_seen(IdxCtx *ctx, dev_t dev, ino_t ino) {
    for (size_t i = 0; i < ctx->n_seen; i++)
        if (ctx->seen[i].dev == dev && ctx->seen[i].ino == ino) return 1;
    if (ctx->n_seen == ctx->cap_seen) {
        size_t nc = ctx->cap_seen ? ctx->cap_seen * 2 : 256;
        ctx->seen = xrealloc(ctx->seen, nc * sizeof(*ctx->seen));
        ctx->cap_seen = nc;
    }
    ctx->seen[ctx->n_seen].dev = dev;
    ctx->seen[ctx->n_seen].ino = ino;
    ctx->n_seen++;
    return 0;
}

static int name_excluded(IdxCtx *ctx, const char *name) {
    for (size_t i = 0; i < ctx->n_excludes; i++)
        if (fnmatch(ctx->excludes[i], name, 0) == 0) return 1;
    return 0;
}

static void update_histogram(uint64_t *hist, uint64_t size) {
    int bucket = 0;
    if (size == 0) { hist[0]++; return; }
    uint64_t v = size;
    while (v > 1 && bucket < 63) { v >>= 1; bucket++; }
    if (bucket >= 64) bucket = 63;
    hist[bucket]++;
}

static void maybe_add_topn(Tree *t, const char *full_path,
                            uint64_t sa, uint64_t sac) {
    if (t->topn_limit == 0) return;
    if (sa < t->topn_min) return;
    if (t->topn_count < t->topn_limit) {
        if (t->topn_count == t->topn_cap) {
            size_t nc = t->topn_cap ? t->topn_cap * 2 : 16;
            if (nc > t->topn_limit) nc = t->topn_limit;
            t->topn = xrealloc(t->topn, nc * sizeof(TopNItem));
            memset(t->topn + t->topn_cap, 0, (nc - t->topn_cap)*sizeof(TopNItem));
            t->topn_cap = nc;
        }
        t->topn[t->topn_count].path = xstrdup(full_path);
        t->topn[t->topn_count].size_apparent = sa;
        t->topn[t->topn_count].size_actual = sac;
        t->topn_count++;
        return;
    }
    size_t min_i = 0;
    for (size_t i = 1; i < t->topn_count; i++)
        if (t->topn[i].size_apparent < t->topn[min_i].size_apparent) min_i = i;
    if (sa > t->topn[min_i].size_apparent) {
        free(t->topn[min_i].path);
        t->topn[min_i].path = xstrdup(full_path);
        t->topn[min_i].size_apparent = sa;
        t->topn[min_i].size_actual = sac;
    }
}

static int scan_dir(IdxCtx *ctx, const char *path, Entry *e, int depth) {
    if (opt_debug) fprintf(stderr, ">> %s\n", path);
    DIR *dir = opendir(path);
    if (!dir) {
        if (!opt_quiet)
            fprintf(stderr, "Skipping %s: %s\n", path, strerror(errno));
        return -1;
    }
    struct dirent *de;
    while ((de = readdir(dir))) {
        if (strcmp(de->d_name, ".") == 0 || strcmp(de->d_name, "..") == 0) continue;
        if (name_excluded(ctx, de->d_name)) continue;
        char full[PATH_MAX];
        snprintf(full, sizeof(full), "%s/%s", path, de->d_name);
        struct stat st;
        if (lstat(full, &st) != 0) continue;
        if (ctx->uid_set && st.st_uid != ctx->uid) continue;
        if (S_ISDIR(st.st_mode)) {
            if (ctx->one_fs && st.st_dev != ctx->root_dev) continue;
            int skip_entry = (ctx->max_depth > 0 && depth + 1 > ctx->max_depth);
            Entry *ce = NULL;
            Entry tmp = {0};
            if (!skip_entry) {
                ce = entry_add_child(e, de->d_name, ENT_DIR);
                ce->dev = (uint64_t)st.st_dev;
            } else {
                entry_init(&tmp, de->d_name, ENT_DIR);
                ce = &tmp;
            }
            scan_dir(ctx, full, ce, depth + 1);
            e->size_apparent += ce->size_apparent;
            e->size_actual += ce->size_actual;
            e->file_count += ce->file_count;
            e->dir_count += ce->dir_count + 1;
            ctx->dir_count++;
            if (skip_entry) entry_free(&tmp);
        } else if (S_ISREG(st.st_mode) || S_ISLNK(st.st_mode) ||
                   S_ISFIFO(st.st_mode) || S_ISBLK(st.st_mode) ||
                   S_ISCHR(st.st_mode) || S_ISSOCK(st.st_mode)) {
            if (ctx->check_hard_links && st.st_nlink > 1 &&
                already_seen(ctx, st.st_dev, st.st_ino)) continue;
            uint64_t sa = (uint64_t)st.st_size;
            uint64_t sac = (uint64_t)st.st_blocks * 512;
            Entry *ce = entry_add_child(e, ctx->hide_file_names ? "" : de->d_name, ENT_FILE);
            ce->size_apparent = sa;
            ce->size_actual = sac;
            e->size_apparent += sa;
            e->size_actual += sac;
            e->file_count += 1;
            ctx->file_count++;
            update_histogram(ctx->tree->hist, sa);
            maybe_add_topn(ctx->tree, full, sa, sac);
            if (opt_debug)
                fprintf(stderr, "    %" PRIu64 " %" PRIu64 " %s\n",
                        sa, sac, de->d_name);
        }
    }
    closedir(dir);
    return 0;
}

