        } else if (strcmp(a, "-e") == 0) {
            o.excludes = xrealloc(o.excludes, (o.n_excludes+1)*sizeof(char*));
            o.excludes[o.n_excludes++] = xstrdup(argv[++i]);
        } else if (strcmp(a, "-H") == 0 || strcmp(a, "--check-hard-links") == 0) o.check_hard_links = 1;
        else if (strcmp(a, "-f") == 0 || strcmp(a, "--force") == 0) o.force = 1;
        else if (strncmp(a, "--fs-exclude=", 13) == 0) {}
        else if (strncmp(a, "--fs-include=", 13) == 0) {}
        else if (strcmp(a, "--hide-file-names") == 0) o.hide_file_names = 1;
        else if (strncmp(a, "--uid=", 6) == 0) { o.uid_set = 1; o.uid = (uid_t)atoi(a + 6); }
        else if (strcmp(a, "-U") == 0) { o.uid_set = 1; o.uid = (uid_t)atoi(argv[++i]); }
        else if (strncmp(a, "--topn=", 7) == 0) o.topn_limit = atoi(a + 7);
        else if (strcmp(a, "-T") == 0) o.topn_limit = atoi(argv[++i]);
        else if (strncmp(a, "--topn-min=", 11) == 0) o.topn_min = strtoull(a + 11, NULL, 10);
        else if (strcmp(a, "-M") == 0) o.topn_min = strtoull(argv[++i], NULL, 10);
        else if (strncmp(a, "--username=", 11) == 0) {
            struct passwd *pw = getpwnam(a + 11);
            if (pw) { o.uid_set = 1; o.uid = pw->pw_uid; }
        } else if (strcmp(a, "-u") == 0) {
            struct passwd *pw = getpwnam(argv[++i]);
            if (pw) { o.uid_set = 1; o.uid = pw->pw_uid; }
        } else if (strncmp(a, "--max-depth=", 12) == 0) o.max_depth = atoi(a + 12);
        else if (strcmp(a, "-m") == 0) o.max_depth = atoi(argv[++i]);
        else if (strcmp(a, "-x") == 0 || strcmp(a, "--one-file-system") == 0) o.one_fs = 1;
        else if (strcmp(a, "-p") == 0 || strcmp(a, "--progress") == 0) o.progress = 1;
        else if (strcmp(a, "--dry-run") == 0) o.dry_run = 1;
