        char *nabs = normalize_path(abspath);
        free(abspath);
        Tree *t = db_add_tree(db, nabs);
        t->timestamp = time(NULL);
        t->topn_limit = o.topn_limit;
        t->topn_min = o.topn_min;
        entry_init(&t->root, nabs, ENT_DIR);
        struct stat st;
        if (lstat(nabs, &st) == 0) t->root.dev = (uint64_t)st.st_dev;
        IdxCtx ctx = {0};
        ctx.tree = t;
