        ctx.excludes = o.excludes;
        ctx.n_excludes = o.n_excludes;
        ctx.one_fs = o.one_fs;
        ctx.root_dev = st.st_dev;
        ctx.uid_set = o.uid_set;
        ctx.uid = o.uid;
        ctx.max_depth = o.max_depth;
        ctx.hide_file_names = o.hide_file_names;
        ctx.bytes = o.bytes;
        scan_dir(&ctx, nabs, &t->root, 0);
        t->root.file_count = ctx.file_count;
