        total_apparent += t->root.size_apparent;
        total_actual += t->root.size_actual;
        free(ctx.seen);
        free(nabs);
    }

    gettimeofday(&t1, NULL);
    double secs = (double)(t1.tv_sec - t0.tv_sec) + (double)(t1.tv_usec - t0.tv_usec) / 1e6;

    if (opt_verbose && !o.dry_run)
