        fmt_size(buf_b, sizeof(buf_b), total_actual, o.bytes);
        fprintf(stderr,
            "Indexed %" PRIu64 " files and %" PRIu64 " directories, "
            "(%s%s apparent, %s%s actual) in %.2f secs.\n",
            total_files, total_dirs > n_paths ? total_dirs - n_paths : 0,
            buf_a, o.bytes ? "" : "B", buf_b, o.bytes ? "" : "B", secs);
    }

    db_free(db);
    free(dbpath); free(o.db);
    for (size_t k=0;k<n_paths;k++) free(paths[k]);
    free(paths);
    for (size_t k=0;k<o.n_excludes;k++) free(o.excludes[k]);
    free(o.excludes);
    return 0;
}
