#include "common.h"

typedef struct {
    char *db;
    int apparent;
    int ascii;
    int bytes;
    int classify;
    int color;
    int count;
    int directory;
    int dirs_only;
    int full_path;
    int graph;
    int levels;
    int name_sort;
    int recursive;
} LsOpts;

static int is_last_child(Entry *parent, size_t idx) {
    return idx + 1 == parent->n_children;
}

/* Print a single entry line. prefix is the tree prefix to print before the entry. */
static void print_entry_line(Entry *parent, Entry *e, LsOpts *o, uint64_t max_size,
                              const char *prefix, int is_tail, int is_root_level,
                              uint64_t parent_total) {
    uint64_t sz;
    if (o->count) sz = (e->type == ENT_DIR) ? (e->file_count + e->dir_count) : 1;
    else sz = o->apparent ? e->size_apparent : e->size_actual;

    char sbuf[64];
    if (o->count) snprintf(sbuf, sizeof(sbuf), "%" PRIu64, sz);
    else fmt_size(sbuf, sizeof(sbuf), sz, o->bytes);

    int width = o->bytes ? 12 : 6;
    printf("%*s %s", width, sbuf, prefix);
    /* name + classify suffix */
    const char *suffix = "";
    if (o->classify) {
        suffix = (e->type == ENT_DIR) ? "/" : "";
    }
    printf("%s%s", e->name ? e->name : "", suffix);
    if (o->classify && suffix[0] == 0 && e->type == ENT_FILE) {
        /* files get trailing space with -F (so columns line up) */
        printf(" ");
    }
    if (o->graph && parent_total > 0) {
        int col_width = 40;
        int fill = (int)(((double)sz / (double)max_size) * col_width + 0.5);
        if (fill > col_width) fill = col_width;
        /* find alignment: find longest name in siblings and pad */
        size_t longest = 0;
        for (size_t i = 0; i < parent->n_children; i++) {
            size_t nl = strlen(parent->children[i].name ? parent->children[i].name : "");
            if (parent->children[i].type == ENT_DIR && o->classify) nl++;
            if (nl > longest) longest = nl;
        }
        size_t cur = strlen(e->name ? e->name : "") + (o->classify && e->type == ENT_DIR ? 1 : 0);
        while (cur < longest + 1) { printf(" "); cur++; }
        printf("[");
        int j;
        /* scale: use sz relative to max in current listing */
        int dots = (int)((double)sz * 43 / (double)max_size + 0.5);
        if (dots > 43) dots = 43;
        if (dots < 0) dots = 0;
        for (j = 0; j < dots; j++) putchar('+');
        for (; j < 43; j++) putchar(' ');
        printf("]");
    }
    printf("\n");
}

/* Recursive tree-view print */
static void print_tree(Entry *e, LsOpts *o, uint64_t max_size_at_top,
                        const char *prefix, int is_root, int level_remaining) {
    /* sort children */
    entry_sort(e, o->name_sort, 0);
    /* figure out max size among siblings */
    uint64_t maxsz = 0;
    for (size_t i = 0; i < e->n_children; i++) {
        Entry *c = &e->children[i];
        if (o->dirs_only && c->type != ENT_DIR) continue;
        uint64_t sz;
        if (o->count) sz = (c->type == ENT_DIR) ? (c->file_count + c->dir_count) : 1;
        else sz = o->apparent ? c->size_apparent : c->size_actual;
        if (sz > maxsz) maxsz = sz;
    }
    if (maxsz == 0) maxsz = 1;
    /* find visible children */
    size_t visible = 0;
    for (size_t i = 0; i < e->n_children; i++)
        if (!(o->dirs_only && e->children[i].type != ENT_DIR)) visible++;

    size_t idx = 0;
    for (size_t i = 0; i < e->n_children; i++) {
        Entry *c = &e->children[i];
        if (o->dirs_only && c->type != ENT_DIR) continue;
        int last = (idx + 1 == visible);
        idx++;

        /* choose connectors. duc uses UTF-8 by default, ASCII with --ascii. */
        const char *connector;
        const char *next_prefix_tail, *next_prefix_mid;
        if (is_root) {
            /* first level */
            if (visible == 1) {
                connector = o->ascii ? "`+- " : "╰┬─ ";
                next_prefix_tail = "    ";
                next_prefix_mid  = "    ";
            } else if (idx == 1) {
                connector = o->ascii ? "`+- " : "╰┬─ ";
                next_prefix_tail = o->ascii ? "  `" : "  ╰";
                next_prefix_mid  = o->ascii ? "  |" : "  │";
            } else if (last) {
                connector = o->ascii ? " `- " : " ╰─ ";
                next_prefix_tail = "    ";
                next_prefix_mid  = "    ";
            } else {
                connector = o->ascii ? " |- " : " ├─ ";
                next_prefix_tail = o->ascii ? "  `" : "  ╰";
                next_prefix_mid  = o->ascii ? "  |" : "  │";
            }
        } else {
            if (last) {
                connector = o->ascii ? "`- " : "╰─ ";
                next_prefix_tail = "    ";
                next_prefix_mid  = "    ";
            } else {
                connector = o->ascii ? "|- " : "├─ ";
                next_prefix_tail = o->ascii ? "|  " : "│  ";
                next_prefix_mid  = o->ascii ? "|  " : "│  ";
            }
        }

        (void)next_prefix_mid;

        /* Build full prefix for this line */
        char full_prefix[4096];
        snprintf(full_prefix, sizeof(full_prefix), "%s%s", prefix, connector);

        print_entry_line(e, c, o, maxsz, full_prefix, last, 0, maxsz);

        if (o->recursive && c->type == ENT_DIR && level_remaining > 1 && c->n_children > 0) {
            char new_prefix[4096];
            snprintf(new_prefix, sizeof(new_prefix), "%s%s",
                     prefix, is_root ? (last ? "    " : (o->ascii ? "  |" : "  │")) :
                                       (last ? "    " : (o->ascii ? "|  " : "│  ")));
            (void)new_prefix;
            /* Simplest: use a fixed 4-space indent per level */
            char new_pref[4096];
            snprintf(new_pref, sizeof(new_pref), "%s%s", prefix,
                     is_root ? "    " : (last ? "    " : (o->ascii ? "|  " : "│  ")));
            print_tree(c, o, max_size_at_top, new_pref, 0, level_remaining - 1);
        }
    }
}

int cmd_ls(int argc, char **argv) {
    LsOpts o = {0};
    o.levels = 4;
    o.ascii = 0;
    char **paths = xmalloc(argc * sizeof(char*));
    size_t n_paths = 0;
    for (int i = 1; i < argc; i++) {
        const char *a = argv[i];
        if (strcmp(a, "-h") == 0 || strcmp(a, "--help") == 0) { print_help_sub("ls"); free(o.db); free(paths); return 0; }
        else if (strcmp(a, "-v") == 0 || strcmp(a, "--verbose") == 0) opt_verbose++;
        else if (strcmp(a, "--debug") == 0) opt_debug = 1;
        else if (strcmp(a, "-q") == 0 || strcmp(a, "--quiet") == 0) opt_quiet = 1;
        else if (strcmp(a, "-a") == 0 || strcmp(a, "--apparent") == 0) o.apparent = 1;
        else if (strcmp(a, "--ascii") == 0) o.ascii = 1;
        else if (strcmp(a, "-b") == 0 || strcmp(a, "--bytes") == 0) o.bytes = 1;
        else if (strcmp(a, "-F") == 0 || strcmp(a, "--classify") == 0) o.classify = 1;
        else if (strcmp(a, "-c") == 0 || strcmp(a, "--color") == 0) o.color = 1;
        else if (strcmp(a, "--count") == 0) o.count = 1;
        else if (strncmp(a, "--database=", 11) == 0) { free(o.db); o.db = xstrdup(a+11); }
        else if (strcmp(a, "-d") == 0) { free(o.db); o.db = xstrdup(argv[++i]); }
        else if (strcmp(a, "-D") == 0 || strcmp(a, "--directory") == 0) o.directory = 1;
        else if (strcmp(a, "--dirs-only") == 0) o.dirs_only = 1;
        else if (strcmp(a, "--full-path") == 0) o.full_path = 1;
        else if (strcmp(a, "-g") == 0 || strcmp(a, "--graph") == 0) o.graph = 1;
        else if (strncmp(a, "--levels=", 9) == 0) o.levels = atoi(a+9);
        else if (strcmp(a, "-l") == 0) o.levels = atoi(argv[++i]);
        else if (strcmp(a, "-n") == 0 || strcmp(a, "--name-sort") == 0) o.name_sort = 1;
        else if (strcmp(a, "-R") == 0 || strcmp(a, "--recursive") == 0) o.recursive = 1;
        else if (a[0] == '-' && a[1] && a[1] != '-') {
            for (const char *p = a+1; *p; p++) {
                if (*p=='v') opt_verbose++;
                else if (*p=='q') opt_quiet=1;
                else if (*p=='a') o.apparent=1;
                else if (*p=='b') o.bytes=1;
                else if (*p=='F') o.classify=1;
                else if (*p=='c') o.color=1;
                else if (*p=='D') o.directory=1;
                else if (*p=='g') o.graph=1;
                else if (*p=='n') o.name_sort=1;
                else if (*p=='R') o.recursive=1;
                else if (*p=='h') { print_help_sub("ls"); return 0; }
                else { fprintf(stderr, "Error: Unknown option '%s'\n", a); return 1; }
            }
        } else paths[n_paths++] = xstrdup(a);
    }
    if (n_paths == 0) {
        char *cwd = getcwd(NULL, 0);
        paths[n_paths++] = cwd ? cwd : xstrdup(".");
    }

