                        for (j = 0; j < dots; j++) putchar('+');
                        for (; j < 53; j++) putchar(' ');
                        putchar(']');
                    }
                    putchar('\n');
                }
            }
        }
        free(norm); free(rel);
    }

    db_free(db); free(dbpath); free(o.db);
    for (size_t k=0;k<n_paths;k++) free(paths[k]);
    free(paths);
    return any_err;
}
