/* Print a single entry line. prefix is the tree prefix to print before the entry. */
static void print_entry_line(Entry *parent, Entry *e, LsOpts *o, uint64_t max_size,
                              const char *prefix, int is_tail, int is_root_level,
                              uint64_t parent_total) {
    uint64_t sz;
    if (o->count) sz = (e->type == ENT_DIR) ? (e->file_count + e->dir_count) : 1;
    else sz = o->apparent ? e->size_apparent : e->size_actual;

