/* Recursive tree-view print */
static void print_tree(Entry *e, LsOpts *o, uint64_t max_size_at_top,
                        const char *prefix, int is_root, int level_remaining) {
    /* sort children */
    entry_sort(e, o->name_sort, 0);
    /* figure out max size among siblings */
    uint64_t maxsz = 0;
    for (size_t i = 0; i < e->n_children; i++) {
        Entry *c = &e->children[i];
        if (o->dirs_only && c->type != ENT_DIR) continue;
        uint64_t sz;
        if (o->count) sz = (c->type == ENT_DIR) ? (c->file_count + c->dir_count) : 1;
        else sz = o->apparent ? c->size_apparent : c->size_actual;
        if (sz > maxsz) maxsz = sz;
    }
    if (maxsz == 0) maxsz = 1;
    /* find visible children */
    size_t visible = 0;
    for (size_t i = 0; i < e->n_children; i++)
        if (!(o->dirs_only && e->children[i].type != ENT_DIR)) visible++;

    size_t idx = 0;
    for (size_t i = 0; i < e->n_children; i++) {
        Entry *c = &e->children[i];
        if (o->dirs_only && c->type != ENT_DIR) continue;
        int last = (idx + 1 == visible);
        idx++;

        /* choose connectors. duc uses UTF-8 by default, ASCII with --ascii. */
        const char *connector;
        const char *next_prefix_tail, *next_prefix_mid;
        if (is_root) {
            /* first level */
            if (visible == 1) {
                connector = o->ascii ? "`+- " : "╰┬─ ";
                next_prefix_tail = "    ";
                next_prefix_mid  = "    ";
            } else if (idx == 1) {
                connector = o->ascii ? "`+- " : "╰┬─ ";
                next_prefix_tail = o->ascii ? "  `" : "  ╰";
                next_prefix_mid  = o->ascii ? "  |" : "  │";
            } else if (last) {
                connector = o->ascii ? " `- " : " ╰─ ";
                next_prefix_tail = "    ";
                next_prefix_mid  = "    ";
            } else {
                connector = o->ascii ? " |- " : " ├─ ";
