                next_prefix_mid  = "    ";
            } else {
                connector = o->ascii ? "|- " : "├─ ";
                next_prefix_tail = o->ascii ? "|  " : "│  ";
                next_prefix_mid  = o->ascii ? "|  " : "│  ";
            }
        }

        (void)next_prefix_mid;

        /* Build full prefix for this line */
        char full_prefix[4096];
        snprintf(full_prefix, sizeof(full_prefix), "%s%s", prefix, connector);

        print_entry_line(e, c, o, maxsz, full_prefix, last, 0, maxsz);

        if (o->recursive && c->type == ENT_DIR && level_remaining > 1 && c->n_children > 0) {
            char new_prefix[4096];
