/* Escape XML text */
static void xml_escape(FILE *f, const char *s) {
    for (const char *p = s; *p; p++) {
        switch (*p) {
            case '&':  fputs("&amp;", f); break;
            case '<':  fputs("&lt;", f); break;
            case '>':  fputs("&gt;", f); break;
            case '"':  fputs("&quot;", f); break;
            case '\'': fputs("&apos;", f); break;
            default:   fputc(*p, f);
        }
    }
