            if (o->exclude_files && c->type != ENT_DIR) continue;
            uint64_t sz = o->apparent ? c->size_apparent : c->size_actual;
            if (sz < o->min_size) continue;
            has_kids = 1; break;
        }
        if (!has_kids) {
            fputs(" />\n", f);
            return;
        }
        fputs(">\n", f);
        for (size_t k = 0; k < e->n_children; k++) {
            Entry *c = &e->children[k];
            if (o->exclude_files && c->type != ENT_DIR) continue;
            uint64_t sz = o->apparent ? c->size_apparent : c->size_actual;
