    { "info",      cmd_info },
    { "ls",        cmd_ls },
    { "topn",      cmd_topn },
    { "xml",       cmd_xml },
    { "json",      cmd_json },
    { "graph",     cmd_graph },
    { "cgi",       cmd_cgi },
    { "gui",       cmd_gui },
    { "ui",        cmd_ui },
    { NULL, NULL }
};

static cmd_fn find_cmd(const char *name) {
    for (int i = 0; cmds[i].name; i++)
        if (strcmp(cmds[i].name, name) == 0) return cmds[i].fn;
    return NULL;
}

int main(int argc, char **argv) {
    /* Handle global options that appear before the subcommand. */
    int i = 1;
    while (i < argc) {
        const char *a = argv[i];
        if (strcmp(a, "--version") == 0) {
            printf("duc version: %s\n", DUC_VERSION);
            printf("options: %s\n", DUC_OPTIONS);
            return 0;
        } else if (strcmp(a, "-h") == 0 || strcmp(a, "--help") == 0) {
            print_usage_top();
            return 0;
        } else if (strcmp(a, "-v") == 0 || strcmp(a, "--verbose") == 0) {
            opt_verbose++; i++;
        } else if (strcmp(a, "-q") == 0 || strcmp(a, "--quiet") == 0) {
            opt_quiet = 1; i++;
        } else if (strcmp(a, "--debug") == 0) {
            opt_debug = 1; i++;
        } else break;
    }

    if (i >= argc) {
        print_usage_top();
        return 0;
    }
    const char *name = argv[i];
    cmd_fn fn = find_cmd(name);
    if (!fn) {
        print_usage_top();
        return 0;
    }
    /* Build sub-argv starting with the subcommand name. */
    int sub_argc = argc - i;
    char **sub_argv = argv + i;
    return fn(sub_argc, sub_argv);
}
