cat > src/cmd_ls.c << 'EOF'
#include "common.h"

typedef struct {
    char *db;
    int apparent;
    int ascii;
    int bytes;
    int classify;
    int color;
    int count;
    int directory;
    int dirs_only;
    int full_path;
    int graph;
    int levels;
    int name_sort;
    int recursive;
} LsOpts;

static uint64_t entry_size(Entry *e, LsOpts *o) {
    if (o->count) return (e->type == ENT_DIR) ? (e->file_count + e->dir_count + 1) : 1;
    return o->apparent ? e->size_apparent : e->size_actual;
}

static void print_name(Entry *e, LsOpts *o, const char *full_prefix) {
    const char *nm = e->name ? e->name : "";
    fputs(nm, stdout);
    if (o->classify) {
        if (e->type == ENT_DIR) fputc('/', stdout);
        else fputc(' ', stdout);
    }
}

static void print_size(uint64_t sz, LsOpts *o) {
    char sbuf[64];
    if (o->count) snprintf(sbuf, sizeof(sbuf), "%" PRIu64, sz);
    else fmt_size(sbuf, sizeof(sbuf), sz, o->bytes);
    int width = o->bytes ? 12 : 6;
    printf("%*s", width, sbuf);
}

/* Visible children filter */
static int is_visible(LsOpts *o, Entry *c) {
    if (o->dirs_only && c->type != ENT_DIR) return 0;
    return 1;
}

/* Recursive tree print. `cont_prefix` is the prefix before the connector. */
static void print_recursive(Entry *e, LsOpts *o, int levels_remaining,
                             const char *cont_prefix, const char *full_path_prefix) {
    /* sort children */
    entry_sort(e, o->name_sort, 0);
    size_t visible = 0;
    for (size_t i = 0; i < e->n_children; i++)
        if (is_visible(o, &e->children[i])) visible++;
    size_t idx = 0;
    for (size_t i = 0; i < e->n_children; i++) {
        Entry *c = &e->children[i];
        if (!is_visible(o, c)) continue;
        int is_first = (idx == 0);
        int is_last  = (idx + 1 == visible);
        idx++;

        const char *conn, *next_cont;
        if (o->ascii) {
            if (is_last)       { conn = " `- "; next_cont = "    "; }
            else if (is_first) { conn = "`+- "; next_cont = " |  "; }
            else               { conn = " |- "; next_cont = " |  "; }
        } else {
            if (is_last)       { conn = " ╰─ "; next_cont = "    "; }
            else if (is_first) { conn = "╰┬─ "; next_cont = " │  "; }
            else               { conn = " ├─ "; next_cont = " │  "; }
        }

        /* Size column */
        print_size(entry_size(c, o), o);
        putchar(' ');
        if (o->full_path) {
            /* no tree, just full relative path */
            if (full_path_prefix && *full_path_prefix)
                fputs(full_path_prefix, stdout);
            print_name(c, o, "");
        } else {
            fputs(cont_prefix, stdout);
            fputs(conn, stdout);
            print_name(c, o, "");
        }
        putchar('\n');

        if (c->type == ENT_DIR && levels_remaining > 0 && c->n_children > 0) {
            char next_prefix[4096];
            snprintf(next_prefix, sizeof(next_prefix), "%s%s", cont_prefix, next_cont);
            char next_fp[4096];
            if (o->full_path) {
                snprintf(next_fp, sizeof(next_fp), "%s%s/",
                         full_path_prefix ? full_path_prefix : "",
                         c->name ? c->name : "");
            } else {
                next_fp[0] = 0;
            }
            print_recursive(c, o, levels_remaining - 1, next_prefix,
                            o->full_path ? next_fp : "");
        }
    }
}

int cmd_ls(int argc, char **argv) {
    LsOpts o = {0};
    o.levels = 4;
    char **paths = xmalloc(argc * sizeof(char*));
    size_t n_paths = 0;
    for (int i = 1; i < argc; i++) {
        const char *a = argv[i];
        if (strcmp(a, "-h") == 0 || strcmp(a, "--help") == 0) {
            print_help_sub("ls"); free(o.db); free(paths); return 0;
        }
        else if (strcmp(a, "-v") == 0 || strcmp(a, "--verbose") == 0) opt_verbose++;
