# We need to sort differently when --count is set. Let's use a local sort instead.
# First add a helper to sort children according to current opts
helper = r'''
/* Sort children of e according to the current options (count-aware). */
static LsOpts *sort_opts_global;
static int ls_cmp_entries(const void *a, const void *b) {
    Entry *ea = (Entry *)a, *eb = (Entry *)b;
    LsOpts *o = sort_opts_global;
    if (o->name_sort) return strcmp(ea->name ? ea->name : "", eb->name ? eb->name : "");
    uint64_t sa = entry_size(ea, o);
    uint64_t sb = entry_size(eb, o);
    if (sa != sb) return (sb > sa) ? 1 : -1;
    return strcmp(ea->name ? ea->name : "", eb->name ? eb->name : "");
}
static void sort_children(Entry *e, LsOpts *o) {
    sort_opts_global = o;
    if (e->n_children)
        qsort(e->children, e->n_children, sizeof(Entry), ls_cmp_entries);
}
'''
# Insert after the entry_size helper
idx = t.find('static uint64_t entry_size(Entry *e, LsOpts *o)')
end = t.find('}\n', idx) + 2
t = t[:end] + helper + t[end:]

# Replace entry_sort calls with sort_children
t = t.replace('entry_sort(e, o->name_sort, 0);', 'sort_children(e, o);')
t = t.replace('entry_sort(e, o.name_sort, 0);', 'sort_children(e, &o);')

open('src/cmd_ls.c','w').write(t)
